import{_ as r,C as o,o as i,c as d,a2 as e,E as n}from"./chunks/framework.CHjbm2Wd.js";const f=JSON.parse('{"title":"The 16-week roadmap","description":"A week-by-week lunar GNC and flight-software plan with deliverables and a capstone.","frontmatter":{"title":"The 16-week roadmap","description":"A week-by-week lunar GNC and flight-software plan with deliverables and a capstone."},"headers":[],"relativePath":"start/roadmap.md","filePath":"start/roadmap.md","lastUpdated":1792993690000}'),s={name:"start/roadmap.md"};function h(l,t,m,c,u,p){const a=o("StudyChecklist");return i(),d("div",null,[t[0]||(t[0]=e('<h1 id="the-16-week-roadmap" tabindex="-1">The 16-week roadmap <a class="header-anchor" href="#the-16-week-roadmap" aria-label="Permalink to &quot;The 16-week roadmap&quot;">​</a></h1><p>This schedule keeps the three-month structure from <code>GNC.md</code> and adds the Month 4 flight-software track. It assumes <strong>12–15 focused hours per week</strong>. At 8–10 hours, stretch it to 24–30 weeks. Do not compress Month 2 to catch up; the GNC core is the part that compounds.</p><p>The weeks are a route, not a contract. If a topic takes two weeks, take two weeks. If you already have the skill, prove it with the deliverable and move on.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Month</th><th>Weeks</th><th>Focus</th><th>Exit deliverable</th></tr></thead><tbody><tr><td><strong>1 · Foundations</strong></td><td>1–4</td><td>Space basics, frames primer, STK, MATLAB/Simulink, C++, Linux, Git, CMake, debugging</td><td>A small C++ lander sim, a lunar STK scenario, and a 1D MATLAB/Simulink model</td></tr><tr><td><strong>2 · GNC core</strong></td><td>5–10</td><td>Frames/time, quaternions, attitude dynamics, PID/LQR, 6DOF, Monte Carlo, navigation, guidance, architecture</td><td>A closed-loop 6DOF descent sim with EKF, controller, guidance, and dispersion results</td></tr><tr><td><strong>3 · Test &amp; integration</strong></td><td>11–12</td><td>V&amp;V, SIL/HIL, Python automation, STK automation</td><td>A test plan, automated test suite, and a repeatable STK study</td></tr><tr><td><strong>4 · Flight software</strong></td><td>13–16</td><td>Real-time C++, Simulink pipeline, cFS, RTOS, CCSDS, NPR 7150.2, fault protection, sensors</td><td>A small flight-software app with requirements, tests, timing evidence, and a fault/mode design</td></tr></tbody></table><h2 id="month-1-·-foundations-weeks-1–4" tabindex="-1">Month 1 · Foundations (weeks 1–4) <a class="header-anchor" href="#month-1-·-foundations-weeks-1–4" aria-label="Permalink to &quot;Month 1 · Foundations (weeks 1–4)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Topics</th><th>Build</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><a href="./../foundations/space-basics.html">Space basics</a>, <a href="./../foundations/frames-primer.html">frames primer</a>, <a href="./../mission/lunar-environment.html">lunar environment</a></td><td>Write a one-page mission profile: PDI altitude, descent phases, key frames, and the numbers you will use.</td></tr><tr><td><strong>2</strong></td><td><a href="./../foundations/stk.html">STK</a>, <a href="./../foundations/matlab-simulink.html">MATLAB &amp; Simulink</a></td><td>Build a lunar orbit/landing-site scenario in STK. Build a 1D vertical lander in Simulink.</td></tr><tr><td><strong>3</strong></td><td><a href="./../foundations/cpp.html">Modern C++</a>, <a href="./../foundations/linux.html">Linux</a></td><td>Write a fixed-memory quaternion and state type in C++ and run it on the command line.</td></tr><tr><td><strong>4</strong></td><td><a href="./../foundations/git.html">Git</a>, <a href="./../foundations/cmake.html">CMake</a>, <a href="./../foundations/debugging.html">debugging</a></td><td>Put the C++ sim in a repo with CMake, tests, a debug build, and a sanitizer run.</td></tr></tbody></table><p><strong>Month 1 done when:</strong> you can run a 1D lander sim, explain every frame and unit in it, reproduce a bug with a debugger, and show a clean build from a fresh clone.</p>',8)),n(a,{id:"month1",title:"Month 1 deliverables",items:"A one-page lunar descent mission profile with phases, frames, and units|A working STK scenario around the Moon with a landing site and an access or lighting report|A 1D vertical lander in MATLAB/Simulink with gravity, thrust, mass flow, and a plot|A C++ fixed-memory quaternion/state library with at least three unit tests|A CMake project that builds in Debug and Release with warnings enabled|A debugger session that finds and fixes a deliberately injected bug"}),t[1]||(t[1]=e('<h2 id="month-2-·-gnc-core-weeks-5–10" tabindex="-1">Month 2 · GNC core (weeks 5–10) <a class="header-anchor" href="#month-2-·-gnc-core-weeks-5–10" aria-label="Permalink to &quot;Month 2 · GNC core (weeks 5–10)&quot;">​</a></h2><p>This is the heart of the plan. Do not rush it.</p><table tabindex="0"><thead><tr><th>Week</th><th>Topics</th><th>Build</th></tr></thead><tbody><tr><td><strong>5</strong></td><td><a href="./../gnc/frames-time.html">Frames, time &amp; transformations</a>, <a href="./../gnc/quaternions.html">quaternions</a></td><td>Implement <code>MCMF → ENU → body</code> transforms and a quaternion attitude state. Test with known vectors.</td></tr><tr><td><strong>6</strong></td><td><a href="./../gnc/attitude-dynamics.html">Attitude dynamics</a></td><td>Add rigid-body rotational dynamics, inertia, RCS torque, and a thrust vector to the sim.</td></tr><tr><td><strong>7</strong></td><td><a href="./../gnc/control.html">PID &amp; LQR</a></td><td>Close an attitude loop. Compare PID and LQR. Add saturation, rate limits, and a deadband.</td></tr><tr><td><strong>8</strong></td><td><a href="./../gnc/sixdof.html">6DOF simulation</a>, <a href="./../gnc/monte-carlo.html">Monte Carlo</a></td><td>Build the full plant. Add sensors, actuators, mass depletion, and a fixed-step integrator. Run dispersions.</td></tr><tr><td><strong>9</strong></td><td><a href="./../gnc/navigation.html">Navigation, EKF &amp; sensor fusion</a></td><td>Add a noisy IMU and altimeter. Estimate altitude, vertical speed, attitude, and gyro bias. Check consistency.</td></tr><tr><td><strong>10</strong></td><td><a href="./../gnc/powered-descent.html">Powered descent guidance</a>, <a href="./../gnc/architecture.html">GNC architecture</a></td><td>Generate throttle/attitude commands from the estimated state. Draw the architecture and rate groups.</td></tr></tbody></table><p><strong>Month 2 done when:</strong> the vehicle can descend from PDI to a target under sensor noise, the controller stays stable at the flight rate, the EKF is consistent, and a 100-run Monte Carlo produces a landing dispersion you can explain.</p>',4)),n(a,{id:"month2",title:"Month 2 deliverables",items:"A frame-conversion module with tests for at least MCMF, ENU, and body frames|A quaternion attitude propagator with normalization and a drift test|A rigid-body model with inertia, RCS torque, thrust torque, and mass depletion|A PID and an LQR attitude controller, both tested with saturation and delay|A 6DOF descent simulation with a fixed-step integrator and logged state|A noisy-sensor EKF with innovation and consistency checks|A powered-descent guidance mode that commands throttle and attitude|A Monte Carlo run of at least 100 cases with percentile results and a written interpretation"}),t[2]||(t[2]=e('<h2 id="month-3-·-test-integration-weeks-11–12" tabindex="-1">Month 3 · Test &amp; integration (weeks 11–12) <a class="header-anchor" href="#month-3-·-test-integration-weeks-11–12" aria-label="Permalink to &quot;Month 3 · Test &amp; integration (weeks 11–12)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Topics</th><th>Build</th></tr></thead><tbody><tr><td><strong>11</strong></td><td><a href="./../test/verification.html">V&amp;V</a>, <a href="./../test/sil-hil.html">SIL &amp; HIL</a></td><td>Write requirements and a test plan for the descent sim. Build a SIL harness. Add fault injection.</td></tr><tr><td><strong>12</strong></td><td><a href="./../test/python-automation.html">Python automation</a>, <a href="./../test/stk-automation.html">STK Object Model</a></td><td>Automate the regression suite. Script an STK access/lighting study and export a report.</td></tr></tbody></table><p><strong>Month 3 done when:</strong> a fresh checkout can run the test suite in one command, the test report maps every requirement to a result, and the STK study can be regenerated with a script rather than a click path.</p>',3)),n(a,{id:"month3",title:"Month 3 deliverables",items:"A requirements list with a unique ID and a test for each requirement|A traceability matrix from requirement to test result|A SIL test that runs the flight-software binary against the plant model|At least three fault-injection tests: stale sensor, bad command, and timing overrun|A pytest suite with fixtures for sim start/stop and a machine-readable report|An STK Object Model script that creates a scenario, computes access or lighting, and saves results"}),t[3]||(t[3]=e('<h2 id="month-4-·-flight-software-weeks-13–16" tabindex="-1">Month 4 · Flight software (weeks 13–16) <a class="header-anchor" href="#month-4-·-flight-software-weeks-13–16" aria-label="Permalink to &quot;Month 4 · Flight software (weeks 13–16)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Topics</th><th>Build</th></tr></thead><tbody><tr><td><strong>13</strong></td><td><a href="./../flight/realtime-cpp.html">Real-time C++</a>, <a href="./../flight/simulink-pipeline.html">Simulink → flight code</a></td><td>Convert the controller to fixed-memory C++. Generate code from a Simulink model and integrate it behind a hand-written interface.</td></tr><tr><td><strong>14</strong></td><td><a href="./../flight/cfs.html">NASA cFS</a>, <a href="./../flight/rtos.html">RTOS</a></td><td>Build a minimal cFS app. Run a task/queue exercise on FreeRTOS or RTEMS. Measure jitter and deadline overruns.</td></tr><tr><td><strong>15</strong></td><td><a href="./../flight/ccsds-spacewire.html">CCSDS &amp; SpaceWire</a>, <a href="./../flight/npr-7150.html">NPR 7150.2</a></td><td>Write a packet parser and a command/telemetry interface. Build an NPR 7150.2 crosswalk for your project.</td></tr><tr><td><strong>16</strong></td><td><a href="./../flight/fault-protection.html">Fault protection</a>, <a href="./../flight/sensors-actuators.html">sensors &amp; actuators</a></td><td>Add a mode manager, FDIR, safe mode, and sensor/actuator fault models. Finish the capstone.</td></tr></tbody></table><p><strong>Month 4 done when:</strong> you can explain the difference between a cyclic executive and an RTOS, show a cFS app exchanging messages, parse a CCSDS-like packet, and defend a fault/mode design for a one-shot landing.</p>',3)),n(a,{id:"month4",title:"Month 4 deliverables",items:"A fixed-memory C++ flight app with no dynamic allocation after initialization|A Simulink controller generated to C and integrated with a handwritten interface|A minimal cFS app with a command, a telemetry point, and an event|A task/queue exercise with measured jitter and a priority-inversion demonstration|A CCSDS-style packet parser with length, APID, sequence, and checksum tests|An NPR 7150.2 crosswalk that maps requirements to evidence without overclaiming compliance|A mode manager with safe mode, abort, and at least three fault-detection paths|A one-page FDIR and timing rationale for the capstone"}),t[4]||(t[4]=e('<h2 id="the-capstone" tabindex="-1">The capstone <a class="header-anchor" href="#the-capstone" aria-label="Permalink to &quot;The capstone&quot;">​</a></h2><p>Build one artifact you can show: <strong>a lunar powered-descent flight-software demo with evidence.</strong></p><p>Minimum scope:</p><ol><li><strong>Plant:</strong> 6DOF lunar descent from PDI, with gravity, thrust, mass flow, RCS, and a landing target.</li><li><strong>Navigation:</strong> IMU + altimeter EKF (attitude may be truth or star-tracker-aided) with noisy measurements.</li><li><strong>Guidance:</strong> phase logic and a throttle/attitude command that reaches the target.</li><li><strong>Control:</strong> PID or LQR attitude loop at a realistic rate, with saturation and deadbands.</li><li><strong>Flight software:</strong> fixed-memory C++ app, message interfaces, mode manager, watchdog, and fault handling.</li><li><strong>V&amp;V:</strong> requirements, traceability, unit tests, SIL run, fault injection, and a Monte Carlo report.</li><li><strong>Story:</strong> a five-minute explanation of the architecture, the three biggest risks, and the evidence that retires them.</li></ol><p>If you can defend that, you can hold a conversation with a lunar-lander flight-software team.</p><h2 id="where-this-deviates-from-gnc-md" tabindex="-1">Where this deviates from <code>GNC.md</code> <a class="header-anchor" href="#where-this-deviates-from-gnc-md" aria-label="Permalink to &quot;Where this deviates from `GNC.md`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Original plan</th><th>This roadmap</th><th>Why</th></tr></thead><tbody><tr><td>STK in Month 1 before coordinate frames</td><td>Short frames primer before STK; full treatment in Month 2</td><td>STK is an exercise in frames and time. Without them, you learn buttons, not astrodynamics.</td></tr><tr><td>Month 1 has eight broad topics</td><td>Compressed tooling, more time on C++/Linux/debugging and the mini sim</td><td>Tool fluency is necessary but not the differentiator. The build is.</td></tr><tr><td>Month 2 has six topics</td><td>Added navigation, guidance, and architecture</td><td>These are the must-master items from <code>GNC.md</code>; they cannot be left implicit.</td></tr><tr><td>Month 3 is SIL/HIL, Python, STK automation</td><td>Added V&amp;V and made it continuous</td><td>Test evidence is a hard constraint for one-shot landing roles.</td></tr><tr><td>No cFS/RTOS/CCSDS/NPR</td><td>Month 4 flight-software track</td><td>These appear in the skills table and in job descriptions.</td></tr><tr><td>“Orbital mechanics lower priority”</td><td>Scoped mission page: two-body, frames, time, descent</td><td>You do not need the full three-body problem, but you do need the descent-relevant parts.</td></tr></tbody></table><h2 id="if-you-only-have-six-weeks" tabindex="-1">If you only have six weeks <a class="header-anchor" href="#if-you-only-have-six-weeks" aria-label="Permalink to &quot;If you only have six weeks&quot;">​</a></h2><p>Do this, in order:</p><ol><li>Frames/time + quaternions.</li><li>6DOF sim + attitude control.</li><li>Navigation/EKF basics.</li><li>Powered descent guidance.</li><li>V&amp;V + one automated test suite.</li><li>Real-time C++ constraints + one cFS or RTOS exercise.</li></ol><p>Skip STK automation, NPR 7150.2 depth, and the full Monte Carlo campaign. You will still be able to build and defend a descent demo.</p><p>Next: <a href="./setup.html">set up your tools</a> or <a href="./progress.html">open the dashboard</a>.</p>',12))])}const b=r(s,[["render",h]]);export{f as __pageData,b as default};
